def reviewed_bytes(path: str) -> bytes:
    """This packet's reviewed bytes of path; a bridged successor projects newer bytes back first."""
    return successor.historical_bytes(path, regular_bytes(path))


def _verified(path: str) -> bytes:
    """reviewed_bytes, checked against its era digest on every read; a path outside the era is refused."""
    raw = reviewed_bytes(path)
    expected = ERA_SHA256.get(path)
    require(expected is not None and digest(raw) == expected, "MAS-RA-000 reviewed bytes are bound: " + path)
    return raw


def _json(path: str) -> Any:
    return parse(_verified(path))


def _bound(check: Any, message: str) -> None:
    """A structural check over a module's result or a record; a malformed one is refused, not raised."""
    try:
        holds = check()
    except (KeyError, TypeError, AttributeError, IndexError, ValueError):
        holds = False
    require(holds is True, message)


def _era_model(path: str, name: str) -> types.ModuleType:
    """A reference module of this era, executed from its verified bytes."""
    module = types.ModuleType(name)
    module.__file__ = str(ROOT / path)
    exec(compile(_verified(path), path, "exec", dont_inherit=True), module.__dict__)
    return module


def _era_reader(path: str) -> bytes:
    """The model's reader: era files are digest-checked; a task packet is absent in this era unless the era's catalog
    holds it (the model only probes proposed IDs, which no packet of this era may use)."""
    if path.startswith("task-packets/"):
        raise FileNotFoundError(path)
    return _verified(path)


def validate_era_bytes() -> None:
    """Every reviewed file of this era is bound by digest before anything is parsed or executed; v1 is frozen."""
    for path in FROZEN_PATHS:
        require(path not in _PROJECTION_RULES, "the MET-ADOPT-002 record, its map and the policy stay byte-identical")
    for path, expected in ERA_SHA256.items():
        require(digest(reviewed_bytes(path)) == expected, "MAS-RA-000 reviewed bytes are bound: " + path)


def validate_research_adoption_v2_status() -> None:
    """Adopted after independent review rounds, each bound to its record, the last a pass on the reviewed subject."""
    status = _json(STATUS_PATH)
    require(type(status) is dict and set(status) == set(STATUS_KEYS)
            and status["schemaVersion"] == "planeon.internal.research-adoption-v2-status/v1"
            and status["workItem"] == "MAS-RA-000" and status["status"] == "ADOPTED_FOR_SOURCE_PUBLICATION"
            and status["reviewedSubject"] == REVIEWED_SUBJECT and status["nonClaims"] == NON_CLAIMS
            and status["successorOf"] == {"record": {"path": PREDECESSOR, "sha256": ERA_SHA256[PREDECESSOR]},
                                          "map": {"path": MAP, "sha256": ERA_SHA256[MAP]}, "by": RECORD}
            and type(status["carried"]) is list
            and all(type(row) is dict and set(row) == {"item", "to", "action"} for row in status["carried"]),
            "adopted MAS-RA-000 status")
    rounds = status["rounds"]
    previous: list = []
    require(type(rounds) is list and all(type(row) is dict for row in rounds)
            and [(row.get("round"), row.get("verdict")) for row in rounds] == list(ROUNDS), "review rounds in order")
    for row in rounds:
        number = row["round"]
        withheld = number in WITHHELD_ROUNDS and number < LAST_ROUND
        require(set(row) == set(ROW_KEYS) | ({"withheld", "publicCopy"} if withheld else set())
                and row["record"] == OVERLAY_DIR + "review-round%d.json" % number
                and row["snapshot"] == (OVERLAY_DIR + "round%d/" % number if number < LAST_ROUND and not withheld
                                        else None), "review round %d row" % number)
        if withheld:
            _bound(lambda: set(row["withheld"]) == {"reason", "sha256"} and type(row["withheld"]["reason"]) is str
                   and row["withheld"]["reason"] != "" and set(row["withheld"]["sha256"]) == set(SUBJECT_FILES)
                   and all(type(v) is str and len(v) == 64 and set(v) <= set("0123456789abcdef")
                           for v in row["withheld"]["sha256"].values())
                   and row["withheld"]["sha256"] == WITHHELD_SHA256, "review round %d withheld subject" % number)
            _bound(lambda: set(row["publicCopy"]) == {"reason", "verbatimSha256"} and row["publicCopy"]["reason"] != ""
                   and row["publicCopy"]["verbatimSha256"] == VERBATIM_RECORD_SHA256,
                   "review round %d public copy" % number)
        record = _json(row["record"])
        require(type(record) is dict and record.get("schemaVersion") == REVIEW_SCHEMA and record.get("round") == number
                and record.get("subjectCommit") == row["subject"] and record.get("subjectTree") == row["subjectTree"]
                and record.get("verdict") == row["verdict"], "review round %d identity" % number)
        actions = record.get("actions")
        require(type(actions) is dict and actions.get("filesEdited") is False and actions.get("personalDataSent") is False
                and actions.get("networkAccessed") == "none",
                "review round %d edited nothing, used no network and sent no personal data" % number)
        findings = record.get("findings")
        dispositions = record.get("dispositions")
        require(type(findings) is list and all(type(item) is dict and item.get("severity") in SEVERITIES for item in findings)
                and row["severities"] == sorted({item["severity"] for item in findings})
                and type(dispositions) is list and all(type(item) is dict and "disposition" in item for item in dispositions)
                and (number > 1 or dispositions == []), "review round %d severities and dispositions" % number)
        if number > 1:   # every finding of the previous round has a recorded disposition
            require({item.get("id") for item in previous} <= {item.get("id") for item in dispositions},
                    "review round %d disposes of every round %d finding" % (number, number - 1))
        previous = findings
    final = rounds[-1]
    require(final["subject"] == REVIEWED_SUBJECT["commit"] and final["subjectTree"] == REVIEWED_SUBJECT["tree"]
            and set(final["severities"]) <= {"NOTE"}, "the passing round reviewed this subject and left notes only")
    require({item["id"] for item in previous} == {row["item"] for row in status["carried"]},
            "every note of the passing round is carried")


def validate_crosswalk() -> None:
    """The record's model from this era's bytes, then the decisions, counts, licence-blocked set, HO-D2 gates and the
    items made ready restated here."""
    summary = _era_model(MODEL, "_met_adopt_003_research_adoption_v2").check(_era_reader)
    _bound(lambda: summary == SUMMARY, "the crosswalk's corpus counts")
    record = _json(RECORD)
    _bound(lambda: [(row["id"], row["selected"]) for row in record["decisions"]] == list(DECISIONS),
           "the owner's decisions Q-RA1 and Q-RA2 and the handover decisions")
    _bound(lambda: sorted(row["id"] for row in record["upstreams"] if row["reuseMode"] == "LICENSE_BLOCKED")
           == sorted(LICENSE_BLOCKED)
           and all(row["licenceCeiling"] == "DESIGN_REFERENCE_ONLY" for row in record["upstreams"]
                   if row["id"] in LICENSE_BLOCKED),
           "the licence-blocked codebases stay design references")
    _bound(lambda: tuple(row["item"] for row in record["acceptance"] if row["readyWhenThisMerges"]) == READY_ON_MERGE
           and {row["item"]: row["gates"] for row in record["acceptance"] if row["gates"]} == GATES
           and all(row["packetPublished"] is False and row["dispatchable"] is False for row in record["acceptance"]),
           "the proposed acceptance IDs, the HO-D2 gates and the items made ready")
    proposed = {row["proposedPacketId"] for row in record["acceptance"] if row["proposedPacketId"] is not None}
    _bound(lambda: not proposed & (set(authority()["baselinePackets"]) | {NEW_PACKET}),
           "no proposed packet ID names a packet of this era")
    _bound(lambda: record["predecessor"]["sha256"] == ERA_SHA256[PREDECESSOR]
           and record["predecessor"]["map"]["sha256"] == ERA_SHA256[MAP]
           and record["licensePolicy"]["sha256"] == ERA_SHA256[POLICY], "the successor binds the byte-identical record")


def validate_research_adoption_v2() -> None:
    """Every reviewed byte and the adoption record first; then the crosswalk from this era."""
    validate_era_bytes()
    validate_research_adoption_v2_status()
    validate_crosswalk()


